        let matchesChange = true;
        if (changeFilter.value === '10') {
          matchesChange = stock.涨跌幅 > 10;
        } else if (changeFilter.value === '20') {
          matchesChange = stock.涨跌幅 > 20;
        } else if (changeFilter.value === 'down') {
          matchesChange = stock.涨跌幅 < 0;
        }

        // 换手率过滤
        let matchesTurnover = true;
        if (turnoverFilter.value === '10') {
          matchesTurnover = stock.换手率 > 10;
        } else if (turnoverFilter.value === '20') {
          matchesTurnover = stock.换手率 > 20;
        } else if (turnoverFilter.value === '30') {
          matchesTurnover = stock.换手率 > 30;
        }

        return matchesSearch && matchesChange && matchesTurnover;
      });
    });

    // 格式化函数
    const formatMoney = (row, column, cellValue) => {
      if (cellValue === undefined) return '';
      return (cellValue / 10000).toLocaleString('zh-CN', {
        maximumFractionDigits: 2,
        minimumFractionDigits: 2
      }) + '万';
    };

    const formatVolume = (row, column, cellValue) => {
      if (cellValue === undefined) return '';
      return (cellValue / 100).toLocaleString('zh-CN', {
        maximumFractionDigits: 0
      });
    };

    const formatPercent = (row, column, cellValue) => {
      if (cellValue === undefined) return '';
      return cellValue.toFixed(2) + '%';
    };

    // 自定义排序
    const sortByChange = (a, b) => {
      return a.涨跌幅 - b.涨跌幅;
    };

    // 初始化图表
    const initCharts = () => {
      // 涨跌幅分布图
      const changeChartInstance = echarts.init(changeChart.value);
      const changeOption = {
        title: {
          text: '涨跌幅分布',
          left: 'center'
        },
        tooltip: {
          trigger: 'axis',
          formatter: '{b}: {c}只股票'
        },
        grid: {
          left: '3%',
          right: '4%',
          bottom: '3%',
          containLabel: true
        },
        xAxis: {
          type: 'category',
          data: ['<0%', '0-10%', '10-20%', '20-30%', '30-40%', '>40%']
        },
        yAxis: {
          type: 'value',
          name: '股票数量'
        },
        series: [{
          name: '股票数量',
          type: 'bar',
          data: [
            stocks.value.filter(s => s.涨跌幅 < 0).length,
            stocks.value.filter(s => s.涨跌幅 >= 0 && s.涨跌幅 < 10).length,
            stocks.value.filter(s => s.涨跌幅 >= 10 && s.涨跌幅 < 20).length,
            stocks.value.filter(s => s.涨跌幅 >= 20 && s.涨跌幅 < 30).length,
            stocks.value.filter(s => s.涨跌幅 >= 30 && s.涨跌幅 < 40).length,
            stocks.value.filter(s => s.涨跌幅 >= 40).length
          ],
          itemStyle: {
            color: function(params) {
              const colors = ['#2ecc71', '#3498db', '#f1c40f', '#e67e22', '#e74c3c', '#c0392b'];
              return colors[params.dataIndex];
            }
          }
        }]
      };
      changeChartInstance.setOption(changeOption);

      // 成交额占比图
      const turnoverChartInstance = echarts.init(turnoverChart.value);
      const turnoverOption = {
        title: {
          text: '成交额占比',
          left: 'center'
        },
        tooltip: {
          trigger: 'item',
          formatter: '{b}: {c}万 ({d}%)'
        },
        legend: {
          orient: 'vertical',
          right: 10,
          top: 'center'
        },
        series: [{
          name: '成交额',
          type: 'pie',
          radius: ['40%', '70%'],
          avoidLabelOverlap: false,
          itemStyle: {
            borderRadius: 10,
            borderColor: '#fff',
            borderWidth: 2
          },
          label: {
            show: false,
            position: 'center'
          },
          emphasis: {
            label: {
              show: true,
              fontSize: '18',
              fontWeight: 'bold'
            }
          },
          labelLine: {
            show: false
          },
          data: stocks.value.map(stock => ({
            value: stock.成交额 / 10000,
            name: stock.名称
          }))
        }]
      };
      turnoverChartInstance.setOption(turnoverOption);

      // 响应窗口大小变化
      window.addEventListener('resize', () => {
        changeChartInstance.resize();
        turnoverChartInstance.resize();
      });
    };

    onMounted(() => {
      initCharts();
    });

    return {
      stocks,
      updateTime,
      searchText,
      changeFilter,
      turnoverFilter,
      filteredStocks,
      avgChangePercent,
      maxChangePercent,
      totalTurnover,
      avgPE,
      avgTurnoverRate,
      formatMoney,
      formatVolume,
      formatPercent,
      sortByChange,
      changeChart,
      turnoverChart
    };
  }
}
</script>

